<?php if(!isset($snapshot['form_mapping']))return;$mapping=$snapshot['form_mapping'];$guideYear=(int)($mapping['year']??0);$guideUrl=(string)($mapping['guide']??\Kulturhus\Verein\TaxPreparation::ELSTER); ?>
<section><h2><?= $escape($taxText('Formularzuordnung')) ?> <?= $escape($mapping['year']) ?> <?= $escape($taxText('– zur Prüfung')) ?></h2>
<?php $mappingState=(string)($mapping['state']??'working_paper'); ?>
<p><strong><?= $escape($taxText('Arbeitsunterlage:')) ?></strong> <?= $escape($taxText('Angaben mit dem Formular für das Abgabejahr abgleichen.')) ?></p>
<p><?= $escape($taxText('Die Werte helfen beim Ausfüllen von Mein ELSTER. Sie sind keine abgegebene oder amtlich geprüfte Steuererklärung. Unbekannte Angaben bleiben offen.')) ?></p>
<?php foreach($mapping['issues'] as $issue): ?><p><?= $escape($issue) ?></p><?php endforeach ?>
<?php foreach($mapping['fields'] as $field): ?><details><summary><?= $escape($field['form'].($field['line']!==null?' · '.$taxText('Zeile').' '.$field['line']:'').' · '.$field['label']) ?></summary><p><strong><?= $field['value']===null||$field['value']===''?$escape($taxText('Noch offen')):($field['unit']==='cents'?$money($field['value']):$escape(is_array($field['value'])?json_encode($field['value'],JSON_UNESCAPED_UNICODE):$field['value'])) ?></strong></p><p><?= $escape($field['origin']) ?></p></details><?php endforeach ?>
<?php foreach($mapping['calculations'] as $calculation): ?><details><summary><?= $escape($calculation['label']) ?>: <?= $escape($taxText('Überleitung ansehen')) ?></summary><p><?= $escape($calculation['formula']) ?></p><p><?= $money($calculation['recorded_income_cents']) ?> − <?= $money($calculation['recorded_expense_cents']) ?> + <?= $money($calculation['add_cents']) ?> − <?= $money($calculation['subtract_cents']) ?> = <?= $money($calculation['reviewed_result_cents']) ?></p><p><?= $escape($calculation['basis']) ?></p><?php foreach($calculation['corrections'] as $correction): ?><p><?= $escape($correction['reason']) ?>: <?= $money($correction['amount_cents']) ?></p><?php endforeach ?></details><?php endforeach ?>
<?php if(!empty($mapping['limitations'])): ?><details><summary><?= $escape($taxText('Grenzen dieser Arbeitsunterlage')) ?></summary><ul><?php foreach($mapping['limitations'] as $limitation): ?><li><?= $escape($limitation) ?></li><?php endforeach ?></ul></details><?php endif ?>
<p><a href="<?= $escape($guideUrl) ?>" target="_blank" rel="noopener noreferrer"><?= $escape($taxText('ELSTER-Hilfe für')) ?> <?= $guideYear>0?$guideYear:$escape($taxText('das Abgabejahr')) ?></a></p></section>
